@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:wght@500;600;700&display=swap');
:root{--ink:#100d18;--panel:#1a1523;--panel2:#211a2c;--muted:#a49aaa;--text:#f7f0e9;--gold:#e5b875;--pink:#dd87a3;--line:#ffffff16;--mint:#9ed7c7}*{box-sizing:border-box}body{margin:0;background:var(--ink);color:var(--text);font:15px 'DM Sans',sans-serif;min-height:100vh;background-image:radial-gradient(ellipse at 74% 3%,#48243c40,transparent 36%),radial-gradient(ellipse at 10% 70%,#1d334029,transparent 35%)}button,input{font:inherit}button{color:inherit}.app-shell{max-width:1280px;min-height:100vh;margin:auto;padding:0 48px;display:flex;flex-direction:column}.topbar{height:83px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line);flex:none}.wordmark{display:flex;align-items:center;gap:12px;color:var(--text);text-decoration:none;font-size:12px;font-weight:700;letter-spacing:2px}.wordmark i{font-style:normal;color:var(--gold);font-weight:500}.brand-mark{width:34px;height:34px;border:1px solid #dcb37c88;border-radius:50%;display:grid;place-items:center;font:20px 'Playfair Display',serif;color:var(--gold)}.top-right{display:flex;align-items:center;gap:19px}.adult-pill{font-size:9px;letter-spacing:1.6px;color:#b5aab8;display:flex;align-items:center;gap:8px}.adult-pill span{width:6px;height:6px;border-radius:50%;background:var(--mint);box-shadow:0 0 9px var(--mint)}.sound-button{width:34px;height:34px;border:1px solid var(--line);background:#ffffff08;border-radius:50%;cursor:pointer;color:var(--gold)}main{flex:1;padding:44px 0 60px}footer{height:53px;border-top:1px solid var(--line);display:flex;justify-content:space-between;align-items:center;color:#817887;font-size:11px;letter-spacing:.3px;flex:none}footer b{color:var(--pink);margin-left:5px}.eyebrow{font-size:10px;font-weight:700;letter-spacing:2.5px;color:var(--gold);text-transform:uppercase}.serif{font-family:'Playfair Display',serif}.hero{min-height:570px;display:grid;grid-template-columns:1.03fr .97fr;align-items:center;gap:20px;position:relative;overflow:hidden}.hero-copy{padding:10px 0 20px;position:relative;z-index:2}.hero h1{font:clamp(54px,7vw,88px)/.99 'Playfair Display',serif;letter-spacing:-3px;margin:21px 0 23px;max-width:630px}.hero h1 em{color:var(--pink);font-weight:500}.hero-copy p{color:#b7acba;max-width:450px;line-height:1.8;font-size:15px}.hero-actions{display:flex;align-items:center;gap:20px;margin-top:35px}.button{border:0;border-radius:4px;padding:14px 21px;font-weight:700;font-size:12px;letter-spacing:.6px;cursor:pointer;transition:transform .18s,filter .18s,background .18s}.button:hover{transform:translateY(-2px);filter:brightness(1.1)}.button-primary{background:var(--gold);color:#201522;box-shadow:0 8px 25px #e5b87527}.button-quiet{background:transparent;color:#c7bac7;text-decoration:underline;text-underline-offset:4px;padding-left:0}.hero-note{color:#817887;font-size:11px}.hero-art{height:510px;position:relative;display:grid;place-items:center}.halo{position:absolute;width:420px;height:420px;border-radius:50%;background:radial-gradient(circle,#b0597145 0,#8241602b 48%,transparent 71%);filter:blur(2px)}.hero-orb{width:310px;height:390px;border-radius:48% 48% 43% 43%;position:relative;overflow:hidden;background:linear-gradient(145deg,#63334d,#211b2c 71%);box-shadow:0 25px 90px #0008, inset 0 0 0 1px #ffffff18}.hero-orb:before{content:'';position:absolute;width:190px;height:230px;top:51px;left:62px;border-radius:48% 48% 42% 42%;background:linear-gradient(115deg,#dbad91,#a9696b 78%);box-shadow:inset -23px -8px 28px #44253c66}.hero-orb:after{content:'';position:absolute;width:235px;height:185px;bottom:-48px;left:39px;border-radius:50% 50% 0 0;background:linear-gradient(105deg,#17151e,#4b3442 57%,#15131b)}.hero-hair{position:absolute;z-index:2;width:190px;height:100px;top:43px;left:56px;background:#201b26;border-radius:55% 52% 24% 25%;transform:rotate(-4deg);box-shadow:inset 18px 4px #47313a}.hero-neck{position:absolute;z-index:1;top:239px;left:132px;width:62px;height:82px;background:#b97977;border-radius:20px}.hero-eye{position:absolute;z-index:3;top:159px;left:111px;width:7px;height:3px;border-radius:50%;background:#34212a;box-shadow:67px 0 #34212a}.hero-eye:after{content:'';position:absolute;top:36px;left:22px;width:37px;height:14px;border-bottom:2px solid #82464e;border-radius:50%}.art-tag{position:absolute;z-index:4;padding:11px 15px;background:#17121edb;border:1px solid #ffffff1a;backdrop-filter:blur(10px);border-radius:4px;font-size:11px;box-shadow:0 10px 35px #0005}.art-tag b{color:var(--gold);font-weight:600}.tag-top{top:85px;right:2px}.tag-bottom{bottom:83px;left:0}.intro-strip{border-top:1px solid var(--line);padding-top:27px;display:flex;align-items:center;justify-content:space-between;color:#918696;font-size:12px}.intro-strip strong{color:#e2d7e2;font-weight:500}.intro-strip .strip-heart{font-size:20px;color:var(--pink)}
.section-head{display:flex;justify-content:space-between;align-items:flex-end;margin-bottom:27px}.section-head h2{font:38px 'Playfair Display',serif;margin:9px 0 0}.step-label{font-size:11px;color:#9e92a1;letter-spacing:1px}.panel{background:linear-gradient(135deg,#211b2a,#18141e);border:1px solid var(--line);border-radius:8px;padding:25px}.customize-layout{display:grid;grid-template-columns:1fr .8fr;gap:28px}.form-panel{display:grid;gap:22px}.field-label{font-size:11px;color:#c3b9c5;display:block;margin-bottom:10px;font-weight:600}.name-input{width:100%;padding:13px 14px;background:#100d18;border:1px solid #ffffff20;border-radius:4px;color:var(--text);outline:none}.name-input:focus{border-color:var(--gold)}.swatches,.choice-row{display:flex;gap:9px;flex-wrap:wrap}.swatch{width:36px;height:36px;border-radius:50%;border:2px solid transparent;cursor:pointer;position:relative}.swatch.selected{border-color:#f8e2c4;box-shadow:0 0 0 2px var(--panel)}.choice-chip{background:#ffffff08;border:1px solid #ffffff1a;color:#c6bbc8;padding:9px 13px;border-radius:4px;cursor:pointer;font-size:11px}.choice-chip.selected{background:#e5b87520;border-color:#e5b87599;color:#f4d5a5}.custom-preview{min-height:410px;display:grid;place-items:center;position:relative;overflow:hidden;background:radial-gradient(ellipse at 50% 43%,#65405266,transparent 54%),linear-gradient(155deg,#211a29,#17131c)}.custom-preview:after{content:'';position:absolute;bottom:32px;width:245px;height:20px;background:#08070b99;filter:blur(13px);border-radius:50%}.avatar{width:220px;height:315px;position:relative;z-index:1}.avatar .body{position:absolute;bottom:0;left:10px;width:200px;height:175px;background:linear-gradient(110deg,#16151f,#453443 58%,#211925);border-radius:48% 48% 9% 9%;clip-path:polygon(24% 0,76% 0,100% 100%,0 100%)}.avatar .neck{position:absolute;top:150px;left:85px;width:50px;height:60px;background:var(--skin);border-radius:10px 10px 22px 22px}.avatar .face{position:absolute;top:45px;left:47px;width:126px;height:150px;background:linear-gradient(110deg,var(--skin),var(--skin-shadow));border-radius:47% 47% 43% 43%;z-index:2}.avatar .hair{position:absolute;z-index:3;top:35px;left:43px;width:132px;height:67px;background:var(--hair);border-radius:55% 50% 25% 22%;transform:rotate(-3deg)}.avatar .hair.long{height:100px;border-radius:57% 51% 33% 30%}.avatar .hair.silver{background:linear-gradient(120deg,#5b596c,#c3bbc7 60%,#787080)}.avatar .eyes{position:absolute;z-index:4;top:111px;left:76px;width:7px;height:4px;border-radius:50%;background:#30212a;box-shadow:64px 0 #30212a}.avatar .mouth{position:absolute;z-index:4;top:159px;left:99px;width:25px;height:8px;border-bottom:2px solid #874957;border-radius:50%}.preview-caption{position:absolute;z-index:3;bottom:20px;left:20px;color:#b7a9b8;font-size:11px}.form-footer{display:flex;align-items:center;justify-content:space-between;gap:15px}.hint{font-size:10px;color:#827889;line-height:1.6}.choice-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:15px}.location-card,.love-card{position:relative;min-height:190px;overflow:hidden;border:1px solid var(--line);border-radius:7px;padding:22px;text-align:left;background:linear-gradient(155deg,#292034,#19141f);cursor:pointer;transition:.2s}.location-card:hover,.love-card:hover{transform:translateY(-3px);border-color:#e5b87577}.location-card:after{content:attr(data-icon);position:absolute;right:15px;bottom:2px;font-size:90px;opacity:.16;filter:grayscale(.4)}.location-card .location-type{font-size:9px;letter-spacing:1.7px;color:var(--gold)}.location-card h3,.love-card h3{font:25px 'Playfair Display',serif;margin:14px 0 8px}.location-card p,.love-card p{color:#a89eae;font-size:11px;line-height:1.6;max-width:290px}.location-card .arrow{position:absolute;right:20px;top:20px;color:var(--gold)}.location-note{margin-top:20px;color:#948999;font-size:11px}
.date-layout{display:grid;grid-template-columns:.75fr 1.25fr;gap:22px}.date-card{background:linear-gradient(155deg,#35243a,#201824);border:1px solid #ffffff1c;border-radius:7px;min-height:440px;position:relative;overflow:hidden;display:flex;align-items:flex-end}.date-card .portrait-bg{position:absolute;inset:0;background:radial-gradient(ellipse at 50% 32%,#d1819055,transparent 52%),linear-gradient(180deg,#342034,#1c1622)}.date-card .portrait-bg:after{content:'';position:absolute;width:185px;height:220px;left:calc(50% - 92px);top:55px;border-radius:49% 49% 43% 43%;background:linear-gradient(120deg,var(--person-skin),#986064);box-shadow:inset -25px -8px 35px #321d3688}.date-card .portrait-hair{position:absolute;z-index:1;left:calc(50% - 100px);top:45px;width:200px;height:89px;background:var(--person-hair);border-radius:55% 52% 23% 24%;transform:rotate(-5deg)}.date-card .portrait-body{position:absolute;width:280px;height:210px;bottom:-68px;left:calc(50% - 140px);border-radius:50% 50% 0 0;background:linear-gradient(110deg,#17151d,#51404c 56%,#211923)}.date-card .portrait-eyes{position:absolute;z-index:2;width:7px;height:4px;background:#37222a;left:calc(50% - 42px);top:159px;border-radius:50%;box-shadow:74px 0 #37222a}.date-card .person-caption{position:relative;z-index:3;padding:22px;background:linear-gradient(transparent,#100d18e8);width:100%}.person-caption .person-title{color:var(--gold);font-size:9px;letter-spacing:2px}.person-caption h3{font:32px 'Playfair Display',serif;margin:5px 0}.person-caption p{font-size:11px;color:#c0b4c1;margin:0}.scene-panel{padding:25px 28px}.scene-meta{display:flex;justify-content:space-between;color:#a89cac;font-size:10px;letter-spacing:1px}.chemistry{display:flex;align-items:center;gap:8px}.heart-meter{color:#db809e;letter-spacing:2px}.dialogue{font:24px/1.5 'Playfair Display',serif;margin:34px 0 27px;min-height:100px}.dialogue em{color:#e8bc83}.choices{display:grid;gap:10px}.dialogue-choice{width:100%;text-align:left;background:#ffffff06;border:1px solid #ffffff1b;border-radius:5px;padding:14px 16px;cursor:pointer;color:#ded4e0;font-size:12px;line-height:1.5;transition:.18s}.dialogue-choice:hover{border-color:#d9af7799;background:#e5b8750b;transform:translateX(3px)}.choice-num{color:var(--gold);padding-right:10px}.scene-bottom{margin-top:22px;padding-top:16px;border-top:1px solid var(--line);display:flex;align-items:center;justify-content:space-between}.consent-note{color:#938899;font-size:10px}.soft-button{background:transparent;border:0;color:#b7a9ba;font-size:11px;text-decoration:underline;text-underline-offset:4px;cursor:pointer}.final-card{max-width:740px;margin:15px auto 0;text-align:center;padding:56px 50px;background:radial-gradient(ellipse at 50% 0%,#713e5940,transparent 54%),linear-gradient(140deg,#211a2b,#17131d);border:1px solid #ffffff1b;border-radius:8px}.final-heart{font-size:35px;color:var(--pink)}.final-card h2{font:42px 'Playfair Display',serif;margin:15px 0}.final-card p{color:#b7adba;line-height:1.8;max-width:540px;margin:0 auto 25px}.ending-stats{display:flex;justify-content:center;gap:30px;margin:27px 0 30px}.ending-stats div{font-size:10px;color:#918697;letter-spacing:1px}.ending-stats b{display:block;color:var(--gold);font:19px 'Playfair Display',serif;margin-bottom:5px}.restart-row{display:flex;gap:10px;justify-content:center}.toast{position:fixed;bottom:70px;left:50%;transform:translate(-50%,20px);background:#eee0cb;color:#211722;padding:11px 18px;border-radius:4px;font-size:12px;opacity:0;pointer-events:none;transition:.2s;z-index:9}.toast.show{opacity:1;transform:translate(-50%,0)}.hidden{display:none!important}
@media(max-width:850px){.app-shell{padding:0 25px}.hero{min-height:520px;grid-template-columns:1fr .8fr}.hero-art{transform:scale(.82);transform-origin:center}.hero h1{font-size:64px}.customize-layout{grid-template-columns:1fr 1fr}.date-layout{grid-template-columns:.8fr 1.2fr}.date-card{min-height:410px}.scene-panel{padding:22px}.dialogue{font-size:21px;margin:25px 0}}
@media(max-width:650px){.app-shell{padding:0 18px}.topbar{height:66px}.top-right{gap:10px}.adult-pill{font-size:8px;letter-spacing:1px}.brand-mark{width:30px;height:30px}.wordmark{font-size:10px;letter-spacing:1.4px}main{padding:28px 0 42px}.hero{display:flex;flex-direction:column;align-items:stretch;min-height:auto;gap:0}.hero-copy{padding:14px 0 0}.hero h1{font-size:57px;margin:17px 0}.hero-copy p{font-size:13px}.hero-art{height:350px;transform:scale(.77);margin:-15px 0 -25px}.hero-actions{margin-top:25px;flex-wrap:wrap;gap:13px}.hero-note{width:100%}.intro-strip{font-size:10px;line-height:1.6;gap:15px}.intro-strip>span:first-child{max-width:220px}.section-head{align-items:flex-start;margin-bottom:20px}.section-head h2{font-size:32px}.step-label{font-size:9px;text-align:right}.customize-layout,.date-layout{grid-template-columns:1fr}.custom-preview{min-height:340px;grid-row:1}.avatar{transform:scale(.86)}.panel{padding:20px}.choice-grid{grid-template-columns:1fr}.location-card{min-height:145px}.date-card{min-height:320px}.date-card .portrait-bg:after{top:40px}.date-card .portrait-eyes{top:144px}.scene-panel{padding:18px}.dialogue{font-size:21px;min-height:0;margin:25px 0}.dialogue-choice{padding:12px}.scene-bottom{align-items:flex-start;gap:10px}.final-card{padding:40px 22px}.final-card h2{font-size:34px}.ending-stats{gap:16px}.form-footer{align-items:flex-start;flex-direction:column}.form-footer .button{width:100%}footer{font-size:9px} }

const app = document.querySelector('#app');
const toast = document.querySelector('#toast');
